import 'dart:convert';

import 'package:flutter_test/flutter_test.dart';
import 'package:semi_design_flutter/src/monaco/platform/defaultAccount/common/defaultAccount.dart'
    as da;
import 'package:semi_design_flutter/src/monaco/platform/policy/common/managedSettingsFreshness.dart'
    as fresh;

Map<String, dynamic> _truth() =>
    (jsonDecode(_truthJson) as Map).cast<String, dynamic>();
Map<String, Object?> _map(Object? v) => (v as Map).cast<String, Object?>();

void main() {
  final t = _truth();

  test('runtime exports match truth', () {
    // Dart carries the interfaces as classes plus the 4 runtime values; the
    // TS runtime surface is exactly the 4 values (interfaces are erased).
    expect(da.IDefaultAccountService.serviceId, t['decoratorId']);
    expect(da.GitHubPaths.copilotSettings, _map(t['GitHubPaths'])['copilotSettings']);
    expect(da.GitHubPaths.billingBudgets, _map(t['GitHubPaths'])['billingBudgets']);
    expect(da.GitHubPaths.copilotUpgrade, _map(t['GitHubPaths'])['copilotUpgrade']);
    expect(da.MANAGED_SETTINGS_UPDATE_REQUIRED_ERROR_CODE,
        t['updateRequiredCode']);
    expect(
        da.reExportedFreshness.state, _map(t['reExportedFreshness'])['state']);
    expect(t['reExportedFreshnessMatches'], true);
    expect(identical(da.reExportedFreshness,
        fresh.MANAGED_SETTINGS_FRESHNESS_NOT_REQUIRED), true);
  });

  test('compatibility error & refresh option carriers are constructible', () {
    final err = da.IManagedSettingsCompatibilityError(
      errorCode: da.MANAGED_SETTINGS_UPDATE_REQUIRED_ERROR_CODE,
      clientVersion: '1.2.3',
      minimumClientVersion: '1.3.0',
    );
    expect(err.errorCode, 'client_update_required');
    expect(err.clientVersion, '1.2.3');
    expect(err.minimumClientVersion, '1.3.0');
    final opts = da.IDefaultAccountRefreshOptions(
      forceRefresh: true,
      refreshEntitlements: false,
      retryManagedSettings: true,
    );
    expect(opts.forceRefresh, true);
    expect(opts.refreshEntitlements, false);
    expect(opts.retryManagedSettings, true);
  });
